	@JvmStatic
	fun debuffedSmall(): PluginImage = image(DEBUFFED_SMALL_WIDTH, DEBUFFED_SMALL_HEIGHT, DEBUFFED_SMALL_PIXELS)

	private fun image(width: Int, height: Int, hex: String): PluginImage {
		val pixels: IntArray = IntArray(width * height)
		for (i in pixels.indices) {
			pixels[i] = hex.substring(i * 8, i * 8 + 8).toLong(16).toInt()
		}
		return PluginImage(width, height, pixels)
	}
